from typing import Dict, List, Optional

import fastjson

from .clock import day_of, parse_day


def upload(readings: List[Dict], since: Optional[str] = None) -> Dict:
    """Encode readings for the uplink and report what was sent."""
    cutoff = parse_day(since)
    in_range = [r for r in readings if cutoff is None or day_of(r["ts"]) >= cutoff]
    sendable = [r for r in in_range if r["temp"] is not None]
    payload = fastjson.dumps(
        {"readings": [[r["ts"], r["sensor"], r["temp"]] for r in sendable]}
    )
    return {
        "sent": len(sendable),
        "payload": payload,
        "skipped": len(in_range) - len(sendable),
    }
"}

